  // the orchestrator would believe the subagent completed.
  const earlierGood = {
    type: "message",
    message: {
      role: "assistant",
      content: [{ type: "text", text: "Investigating the bug..." }],
    },
  };
  const overloadError = {
    type: "message",
    message: {
      role: "assistant",

      role: "assistant",
      content: [{ type: "text", text: "Investigating the bug..." }],
    },
  };
  const overloadError = {
    type: "message",
    message: {
      role: "assistant",
      content: [],
      stopReason: "error",
      errorMessage: "Anthropic 529 Overloaded after 3 retries",
    },
  };
