describe("runningChildrenCount", () => {
  const KEY = Symbol.for("pi-subagents/running-children-count");
  function withGlobal(value: unknown, run: () => void) {
    const prev = (globalThis as any)[KEY];
    (globalThis as any)[KEY] = value;
