  const output = rendered.render(80).join("\n");

  assert.match(output, /Subagent status/);
  for (const line of visibleLines) {
    assert.match(output, new RegExp(line.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")));
  }
  assert.match(output, /\+2 more running\./);
});

